INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000170090','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000170090","revision":1,"targetId":"80000000-0000-4000-8000-000000001709","prompt":"Nach der Landung in Wien muss Nora in ein anderes Flugzeug nach Rom umsteigen. Ihr ___ startet in 50 Minuten.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The traveler changes aircraft to continue the same journey.","de":"Die Person steigt auf derselben Reise in ein anderes Flugzeug um."},"options":[{"id":"0","text":"Rückflug"},{"id":"1","text":"Direktflug"},{"id":"2","text":"Anschlussflug"},{"id":"3","text":"Testflug"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"An Anschlussflug is an onward flight reached by changing planes; the word describes its connection to the preceding flight.","de":"Ein Anschlussflug ist ein Weiterflug nach dem Umsteigen; das Wort beschreibt den Anschluss an den vorherigen Flug."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach der Landung in Wien muss Nora in ein anderes Flugzeug nach Rom umsteigen. Ihr Anschlussflug startet in 50 Minuten.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L89 (cb5874b199c4e07412f79152864ee28f974eab3e422c0713a33948cb9b557387), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
