INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000170091','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000170091","revision":1,"targetId":"80000000-0000-4000-8000-000000001709","prompt":"Die Reisenden mussten in Kopenhagen umsteigen. Weil der erste Flug verspätet war, verpassten sie den ___ nach Oslo.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The traveler changes aircraft to continue the same journey.","de":"Die Person steigt auf derselben Reise in ein anderes Flugzeug um."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Rundflug"},{"id":"1","text":"Anschlussflug"},{"id":"2","text":"Direktflug"},{"id":"3","text":"Probeflug"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"An Anschlussflug is an onward flight reached by changing planes; the word describes its connection to the preceding flight.","de":"Ein Anschlussflug ist ein Weiterflug nach dem Umsteigen; das Wort beschreibt den Anschluss an den vorherigen Flug."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Reisenden mussten in Kopenhagen umsteigen. Weil der erste Flug verspätet war, verpassten sie den Anschlussflug nach Oslo.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/nouns.jsonl:L89 (cb5874b199c4e07412f79152864ee28f974eab3e422c0713a33948cb9b557387), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
