INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000180010','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000180010","revision":1,"targetId":"80000000-0000-4000-8000-000000001801","prompt":"Das Labor hat ein neues Prüfverfahren entwickelt. Ab morgen wird es diese Methode ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The procedure is being used in practice, not invented.","de":"Das Verfahren wird praktisch eingesetzt und nicht erst erfunden."},"options":[{"id":"0","text":"erfinden"},{"id":"1","text":"anwenden"},{"id":"2","text":"ablehnen"},{"id":"3","text":"verlieren"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"Anwenden means applying a method. In a simple finite main-clause form it separates: wir wenden sie an. With a modal or werden plus infinitive, anwenden remains whole.","de":"Anwenden heißt, eine Methode einzusetzen. In der einfachen finiten Hauptsatzform ist es getrennt: wir wenden sie an. Nach einem Modalverb oder werden bleibt der Infinitiv anwenden zusammen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Labor hat ein neues Prüfverfahren entwickelt. Ab morgen wird es diese Methode anwenden.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/verbs.jsonl:L78 (f8c286d0592ba80a480c834ee2725c7f4f346fcf3860184f5e823eead2ac35a9), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
