INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000180100','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000180100","revision":1,"targetId":"80000000-0000-4000-8000-000000001810","prompt":"Die Schlüssel liegen auf dem Boden. Kannst du sie bitte ___?","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"An object has fallen and needs to be lifted from the floor.","de":"Ein Gegenstand liegt auf dem Boden und soll hochgenommen werden."},"options":[{"id":"0","text":"aufgeben"},{"id":"1","text":"aufbauen"},{"id":"2","text":"aufheben"},{"id":"3","text":"auflösen"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Aufheben means to pick up here; it has other senses such as keep or abolish.","de":"Aufheben bedeutet hier hochnehmen; es kann auch aufbewahren oder abschaffen bedeuten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Schlüssel liegen auf dem Boden. Kannst du sie bitte aufheben?","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/verbs.jsonl:L91 (065dfdaffdfd37572952c494583c52861e4b9dbe665d3e5c3e74d64eb1c82cce), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
