INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000180101','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000180101","revision":1,"targetId":"80000000-0000-4000-8000-000000001810","prompt":"Das Kind ließ den Stift fallen und ___ ihn sofort wieder auf.","instruction":{"en":"Choose the verb for physically lifting the dropped pen from the floor.","de":"Wähle das Verb für das Hochnehmen des heruntergefallenen Stifts vom Boden."},"hint":{"en":"An object has fallen and needs to be lifted from the floor.","de":"Ein Gegenstand liegt auf dem Boden und soll hochgenommen werden."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"schloss"},{"id":"1","text":"hob"},{"id":"2","text":"fragte"},{"id":"3","text":"schrieb"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"Aufheben means to pick up here; it has other senses such as keep or abolish.","de":"Aufheben bedeutet hier hochnehmen; es kann auch aufbewahren oder abschaffen bedeuten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Kind ließ den Stift fallen und hob ihn sofort wieder auf.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/verbs.jsonl:L91 (065dfdaffdfd37572952c494583c52861e4b9dbe665d3e5c3e74d64eb1c82cce), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
