INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000180120','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000180120","revision":1,"targetId":"80000000-0000-4000-8000-000000001812","prompt":"Der Akku ist fast leer. Ich muss mein Telefon ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The device needs electrical energy before use.","de":"Das Gerät benötigt vor der Benutzung elektrische Energie."},"options":[{"id":"0","text":"aufheben"},{"id":"1","text":"aufhalten"},{"id":"2","text":"aufladen"},{"id":"3","text":"aufgeben"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Aufladen means charging a battery. A simple finite main clause uses lädt … auf; a modal or future construction keeps the infinitive aufladen whole.","de":"Aufladen bedeutet, einen Akku zu laden. Die einfache finite Hauptsatzform lautet lädt … auf; mit Modalverb oder im Futur bleibt der Infinitiv aufladen zusammen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Akku ist fast leer. Ich muss mein Telefon aufladen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/verbs.jsonl:L94 (5d5bebeea8924fe564ba0812349d2b7999b1bca11eb3a7182cc6695ffd3691c2), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
