INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000180150','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000180150","revision":1,"targetId":"80000000-0000-4000-8000-000000001815","prompt":"Nach der letzten Aufführung beschloss die Theatergruppe, sich endgültig ___.","instruction":{"en":"Choose the expression that completes the sentence accurately.","de":"Wähle den Ausdruck, der den Satz inhaltlich richtig ergänzt."},"hint":{"en":"The organization is being ended rather than established.","de":"Die Organisation wird beendet und nicht neu gegründet."},"options":[{"id":"0","text":"aufzuladen"},{"id":"1","text":"aufzuführen"},{"id":"2","text":"aufzulösen"},{"id":"3","text":"aufzuhalten"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Auflösen means disband or dissolve an organization in these contexts.","de":"Auflösen bezeichnet hier das Auflösen einer Gruppe oder Organisation."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach der letzten Aufführung beschloss die Theatergruppe, sich endgültig aufzulösen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 contexts from pinned source apps/web/data/pos/verbs.jsonl:L97 (3b4fa90ff8c289f475255d7e69fdca9cfdf5d4eb05481ebe2bd0638d3ea0327f), 2026-10-28; no inherited example copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
