INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000790000','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000790000","revision":1,"targetId":"80000000-0000-4000-8000-000000007900","prompt":"Auf den steuerpflichtigen Arbeitslohn wird ___ erhoben.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"This tax concerns a person''s taxable earnings.","de":"Diese Steuer bezieht sich auf steuerpflichtige persönliche Einkünfte."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Umsatzsteuer"},{"id":"1","text":"Gewerbesteuer"},{"id":"2","text":"Einkommensteuer"},{"id":"3","text":"Grundsteuer"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"2"}]}],"explanation":{"en":"Einkommensteuer means income tax. This tax concerns a person''s taxable earnings.","de":"Einkommensteuer bedeutet Steuer auf steuerpflichtige Einkünfte. Diese Steuer bezieht sich auf steuerpflichtige persönliche Einkünfte."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Auf den steuerpflichtigen Arbeitslohn wird Einkommensteuer erhoben.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L600 (c423c0708bcc48c8b81d341002c18f4fff9398056819aa70b5ec09f6fc2ef696), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
