INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000790010','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000790010","revision":1,"targetId":"80000000-0000-4000-8000-000000007901","prompt":"Für die Steuererklärung müssen alle ___ aus Vermietung angegeben werden.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"Rent can generate taxable income.","de":"Vermietung kann steuerpflichtige Einnahmen bringen."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Ausgaben"},{"id":"1","text":"Einkünfte"},{"id":"2","text":"Schulden"},{"id":"3","text":"Gebühren"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"1"}]}],"explanation":{"en":"Einkunft means income from a particular source. Rent can generate taxable income.","de":"Einkunft bedeutet Einnahme aus einer bestimmten Quelle. Vermietung kann steuerpflichtige Einnahmen bringen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für die Steuererklärung müssen alle Einkünfte aus Vermietung angegeben werden.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L601 (5d3a1edf5e271b4deadd419623e1d113094a6a4003cdb6d67d80aaa836fc5f48), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
