INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000790020','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000790020","revision":1,"targetId":"80000000-0000-4000-8000-000000007902","prompt":"Vor der Blutentnahme zog die Pflegekraft ___ an.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"Medical hygiene requires a glove that is discarded after use.","de":"Für die Hygiene wird ein Handschuh nach der Verwendung entsorgt."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Einmalhandschuhe"},{"id":"1","text":"Wollhandschuhe"},{"id":"2","text":"Gartenhandschuhe"},{"id":"3","text":"Winterhandschuhe"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Einmalhandschuh means single-use protective glove. Medical hygiene requires a glove that is discarded after use.","de":"Einmalhandschuh bedeutet Handschuh zum einmaligen Gebrauch. Für die Hygiene wird ein Handschuh nach der Verwendung entsorgt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Vor der Blutentnahme zog die Pflegekraft Einmalhandschuhe an.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L603 (ce2f099d513bf1383d250162ebac04e488828146664a97456bb909b63a65095a), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
