INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000790060','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000790060","revision":1,"targetId":"80000000-0000-4000-8000-000000007906","prompt":"Wegen der Baustelle gibt es eine ___ des Zugverkehrs.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"The construction work limits the normal service.","de":"Die Bauarbeiten begrenzen den regulären Verkehr."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Einschränkung"},{"id":"1","text":"Erweiterung"},{"id":"2","text":"Verbesserung"},{"id":"3","text":"Erhöhung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Einschränkung means restriction or limitation. The construction work limits the normal service.","de":"Einschränkung bedeutet Begrenzung von Möglichkeiten oder Funktionen. Die Bauarbeiten begrenzen den regulären Verkehr."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Wegen der Baustelle gibt es eine Einschränkung des Zugverkehrs.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L607 (9135b121335e6084c11dfede46c53cd9c30db7a77c63952e8ad381421d9f448d), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
