INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000810020','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000810020","revision":1,"targetId":"80000000-0000-4000-8000-000000008102","prompt":"Der ___ in die neue Wohnung ist für Samstag geplant.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"The person is beginning to live in the new home.","de":"Die Person beginnt, in der neuen Wohnung zu wohnen."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Auszug"},{"id":"1","text":"Einbruch"},{"id":"2","text":"Einzug"},{"id":"3","text":"Rückzug"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"2"}]}],"explanation":{"en":"Einzug means moving into a new place. The person is beginning to live in the new home.","de":"Einzug bedeutet Beziehen einer neuen Wohnung oder eines Gebäudes. Die Person beginnt, in der neuen Wohnung zu wohnen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Einzug in die neue Wohnung ist für Samstag geplant.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L625 (4d1c1a3836b9ee7522723441951fe1c6268e3a6a0e13cb43ec81b32025b892b0), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
