INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000810030','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000810030","revision":1,"targetId":"80000000-0000-4000-8000-000000008103","prompt":"Zu Beginn des Workshops stellte sie eine lustige Frage als ___.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"The question helps strangers start talking.","de":"Die Frage erleichtert den ersten Kontakt."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Fragebogen"},{"id":"1","text":"Eisbrecher"},{"id":"2","text":"Ablaufplan"},{"id":"3","text":"Zeitmesser"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"1"}]}],"explanation":{"en":"Eisbrecher means icebreaker, figurative or literal. The question helps strangers start talking.","de":"Eisbrecher bedeutet Mittel zum Gesprächseinstieg oder Schiff, das Eis bricht. Die Frage erleichtert den ersten Kontakt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Zu Beginn des Workshops stellte sie eine lustige Frage als Eisbrecher.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L627 (54ac92eed4f5150e354de140ce8d2576524090bbe3dcd30c339fa39c3ca50acf), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
